:root {
  color-scheme: light;
  --ink: #16222e;
  --muted: #5d7185;
  --line: #dbe4ee;
  --paper: #ffffff;
  --bg: #eef3fa;
  --accent: #1f6feb;
  --accent-soft: #e8f0fe;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans SC",
    system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--ink);
  background: var(--bg);
  -webkit-text-size-adjust: 100%;
}

/* 三块结构：顶部标题、左侧菜单、右侧内容 */
.layout {
  display: grid;
  grid-template-rows: auto 1fr;
  min-height: 100vh;
  min-width: 0;
}

.topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 14px;
  padding: 22px 28px;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}

.topbar h1 {
  margin: 0;
  font-size: 24px;
  line-height: 1.35;
  letter-spacing: 0.01em;
  overflow-wrap: anywhere;
}

.topbar .tag {
  margin: 0;
  font-size: 14px;
  color: var(--muted);
}

.body {
  display: flex;
  align-items: stretch;
  min-width: 0;
}

/* 左侧菜单 */
.sidebar {
  flex: 0 0 208px;
  background: var(--paper);
  border-right: 1px solid var(--line);
  padding: 16px 12px;
  min-width: 0;
}

.menu {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.menu-item {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 44px;
  padding: 0 14px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 15px;
  line-height: 1.4;
  text-align: left;
  cursor: pointer;
  white-space: nowrap;
}

.menu-item:hover {
  background: #f1f5fb;
}

.menu-item:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.menu-item[aria-current="page"] {
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: 600;
}

/* 右侧内容 */
.content {
  flex: 1 1 auto;
  min-width: 0;
  padding: 28px;
}

.panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 28px 30px;
}

.panel h2 {
  margin: 0 0 12px;
  font-size: 22px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.panel p {
  margin: 0;
  font-size: 15px;
  line-height: 1.8;
  color: var(--muted);
  overflow-wrap: anywhere;
}

/* 概览统计卡片：宽屏并排，窄屏自动换行 */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  margin: 22px 0 0;
  padding: 0;
  list-style: none;
}

.card {
  min-width: 0;
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fafcff;
}

.card-label {
  margin: 0 0 10px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--muted);
}

.card-value {
  margin: 0;
  font-size: 22px;
  line-height: 1.4;
  font-weight: 600;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.next-up {
  margin-top: 22px;
  padding: 18px 20px;
  border: 1px dashed #c3d4e8;
  border-radius: 12px;
  background: #f5f9ff;
}

.next-up h3 {
  margin: 0 0 8px;
  font-size: 16px;
  line-height: 1.5;
}

.next-up p {
  margin: 0;
  font-size: 15px;
  line-height: 1.8;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.data-note {
  margin: 18px 0 0;
  font-size: 13px;
  line-height: 1.7;
  color: var(--muted);
  overflow-wrap: anywhere;
}

/* 设备筛选 */
.filters {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
}

.filter-field {
  display: flex;
  flex: 1 1 160px;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.filter-field:first-child {
  flex: 2 1 220px;
}

.filter-label {
  font-size: 13px;
  line-height: 1.5;
  color: var(--muted);
}

.filter-control {
  width: 100%;
  min-height: 40px;
  padding: 0 10px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 14px;
}

.filter-control:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.clear-button {
  flex: 0 0 auto;
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: #f5f9ff;
  color: var(--ink);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.clear-button:hover {
  background: #eaf1fb;
}

.clear-button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.table-empty {
  margin: 14px 0 0;
  padding: 18px;
  border: 1px dashed var(--line);
  border-radius: 10px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
}

/* 设备详情 */
.device-detail {
  margin-top: 22px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fafcff;
}

.detail-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.detail-head h3 {
  margin: 0;
  font-size: 17px;
  line-height: 1.4;
}

.detail-close {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.detail-close:hover {
  background: #eef4fb;
}

.detail-close:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.detail-facts {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 10px 20px;
  margin: 16px 0 0;
}

.detail-facts dt {
  font-size: 13px;
  line-height: 1.6;
  color: var(--muted);
}

.detail-facts dd {
  margin: 0;
  font-size: 15px;
  line-height: 1.6;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.device-detail h4 {
  margin: 20px 0 0;
  font-size: 15px;
  line-height: 1.5;
}

.device-detail .table-wrap {
  margin-top: 10px;
}

.detail-table {
  min-width: 520px;
}

.detail-empty {
  margin-top: 12px;
}

/* 设备表格 */
.table-wrap {
  margin-top: 18px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  min-width: 620px;
  margin-top: 14px;
  border-collapse: collapse;
  font-size: 14px;
}

.data-table th,
.data-table td {
  padding: 10px 12px;
  text-align: left;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}

.data-table th {
  background: #f7fafd;
  color: var(--muted);
  font-weight: 600;
}

.data-table tbody tr:hover {
  background: #fafcff;
}

.online-badge {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 13px;
  line-height: 1.6;
}

.online-badge.is-online {
  background: #e7f6ec;
  color: #157f3b;
}

.online-badge.is-offline {
  background: #fdecea;
  color: #b42318;
}

.online-badge.is-unknown {
  background: #eef2f6;
  color: var(--muted);
}

.row-action {
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--accent);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.row-action:hover {
  background: var(--accent-soft);
}

.table-summary {
  margin: 12px 0 0;
  font-size: 13px;
  line-height: 1.7;
  color: var(--muted);
}

.table-status {
  margin: 16px 0 0;
  font-size: 15px;
  line-height: 1.7;
  color: var(--muted);
}

.table-error {
  margin-top: 16px;
  padding: 16px 18px;
  border: 1px dashed #e3b4ae;
  border-radius: 10px;
  background: #fff8f7;
}

.table-error .table-status {
  margin: 0;
  color: #b42318;
}

.retry-button {
  min-height: 44px;
  margin-top: 12px;
  padding: 0 18px;
  border: 1px solid var(--accent);
  border-radius: 8px;
  background: var(--accent);
  color: #ffffff;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.retry-button:hover {
  background: #1a5fd0;
}

.retry-button:focus-visible,
.row-action:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* 窄屏：菜单改为横向可滚动条，主内容不再被挤出屏幕 */
@media (max-width: 720px) {
  .topbar {
    padding: 18px 18px;
  }

  .topbar h1 {
    font-size: 20px;
  }

  .body {
    flex-direction: column;
  }

  .sidebar {
    flex: 0 0 auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
    padding: 8px 10px;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .menu {
    flex-direction: row;
    gap: 6px;
    width: max-content;
  }

  .menu-item {
    width: auto;
    min-height: 40px;
    padding: 0 12px;
    font-size: 14px;
  }

  .content {
    padding: 16px;
  }

  .panel {
    padding: 20px 18px;
  }

  .panel h2 {
    font-size: 19px;
  }
}

// 校园值班台 · 菜单切换 + 概览/设备数据（第02课第2步）
