  font-weight: 600;
}

.data-table tbody tr:hover {
  background: #fafcff;
}

.online-badge {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 13px;
  line-height: 1.6;
}

.online-badge.is-online {
  background: #e7f6ec;
  color: #157f3b;
}

.online-badge.is-offline {
  background: #fdecea;
  color: #b42318;
}

.online-badge.is-unknown {
  background: #eef2f6;
  color: var(--muted);
}

.row-action {
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--accent);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.row-action:hover {
  background: var(--accent-soft);
}

.table-summary {
  margin: 12px 0 0;
  font-size: 13px;
  line-height: 1.7;
  color: var(--muted);
}

.table-status {
  margin: 16px 0 0;
  font-size: 15px;
  line-height: 1.7;
  color: var(--muted);
}

.table-error {
  margin-top: 16px;
  padding: 16px 18px;
  border: 1px dashed #e3b4ae;
  border-radius: 10px;
  background: #fff8f7;
}

.table-error .table-status {
  margin: 0;
  color: #b42318;
}

.retry-button {
  min-height: 44px;
  margin-top: 12px;
  padding: 0 18px;
  border: 1px solid var(--accent);
  border-radius: 8px;
  background: var(--accent);
  color: #ffffff;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.retry-button:hover {
